pub const TestReporterAgent = struct {
    handle: ?*Handle = null,

pub export fn Bun__TestReporterAgentEnable(agent: *Handle) void {
            if (VirtualMachine.get().debugger) |*debugger| {
                _ = &debugger;
                _ = debug("enable", .{});
                (debugger.*).test_reporter_agent.handle = agent;
                _ = retroactivelyReportDiscoveredTests(agent);
            }
    }

pub fn retroactivelyReportDiscoveredTests(agent: *Handle) void {
            const Jest = jsc.Jest.Jest;
            const runner = ((Jest.runner) orelse { return; });
            const active_file = ((runner.bun_test_root.active_file.get()) orelse { return; });
            switch (active_file.phase) {
.collection, .execution => {

},
.done => {
return;
},
}
            const file_path = runner.files.get(active_file.file_id).source.path.text;
            var source_url = bun.String.init(file_path);
            _ = &source_url;
            var max_id: i32 = 0;
            _ = &max_id;
            const root_scope = active_file.collection.root_scope;
            _ = retroactivelyReportScope(agent, root_scope, -1, (&max_id), (&source_url));
            _ = debug("retroactively reported {} tests", .{ max_id });
    }

pub fn retroactivelyReportScope(agent: *Handle, scope: *bun_test.DescribeScope, parent_id: i32, max_id: *i32, source_url: *bun.String) void {
            for (scope.entries.items) |*entry| {
                _ = &entry;
                switch ((entry.*)) {
.describe => |describe| {
if ((describe.base.test_id_for_debugger == 0)) {
                    max_id.* = (max_id.* + 1);
                    const test_id = max_id.*;
                    describe.base.test_id_for_debugger = test_id;
                    var name = bun.String.init((((if (@typeInfo(@TypeOf(describe.base)) == .@"enum" or @typeInfo(@TypeOf(describe.base)) == .@"union") @tagName(describe.base) else describe.base.name)) orelse ("(unnamed)")));
                    _ = &name;
                    _ = agent.reportTestFoundWithLocation(test_id, (&name), .describe, parent_id, source_url, @intCast(describe.base.line_no));
                    _ = retroactivelyReportScope(agent, describe, test_id, max_id, source_url);
                } else {
                    _ = retroactivelyReportScope(agent, describe, describe.base.test_id_for_debugger, max_id, source_url);
                }
},
.test_callback => |test_entry| {
if ((test_entry.base.test_id_for_debugger == 0)) {
                    max_id.* = (max_id.* + 1);
                    const test_id = max_id.*;
                    test_entry.base.test_id_for_debugger = test_id;
                    var name = bun.String.init((((if (@typeInfo(@TypeOf(test_entry.base)) == .@"enum" or @typeInfo(@TypeOf(test_entry.base)) == .@"union") @tagName(test_entry.base) else test_entry.base.name)) orelse ("(unnamed)")));
                    _ = &name;
                    _ = agent.reportTestFoundWithLocation(test_id, (&name), .@"test", parent_id, source_url, @intCast(test_entry.base.line_no));
                }
},
}
            }
    }

