            if ((self.id == 0)) {
                return;
            }
            _ = didCancelAsyncCall(globalObject, .EventListener, self.id);
    }

pub fn willDispatch(self: AsyncTaskTracker, globalObject: *JSGlobalObject) void {
            if ((self.id == 0)) {
                return;
            }
            _ = willDispatchAsyncCall(globalObject, .EventListener, self.id);
    }

pub fn didDispatch(self: AsyncTaskTracker, globalObject: *JSGlobalObject) void {
            if ((self.id == 0)) {
                return;
            }
            _ = didDispatchAsyncCall(globalObject, .EventListener, self.id);
    }
};

